Inheritance.example:
#include <iostream>
using namespace std;

class Animal
{
public:
    void sound()
    {
        cout << "Animal makes a sound" << endl;
    }
};

class Dog : public Animal
{
public:
    void bark()
    {
        cout << "Dog barks" << endl;
    }
};

int main()
{
    Dog d;
    d.sound();   // inherited
    d.bark();    // own function
}

Polymorphism.example:
class Animal
{
public:
    virtual void sound() { cout << "Animal"; }
};

class Dog : public Animal
{
public:
    void sound() override { cout << "Dog"; }
};

